head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > P > confirmFalseAction]<br/>useConfirmMessage=true 일때 중복 Tab 페이지 추가 시 표시되는 Confirm 창에 출력할 텍스트를 설정합니다.",
    "validation" : [
        "addTab() 메소드로 Tab 페이지를 추가할때 동일 ID 의 Tab 페이지가 있는 경우 Confirm 창이 표시됩니다.",
        "미설정 또는 new 설정 시 설정한 ID 에 '_{index}' 형식의 Suffix 를 붙여 새로운 Tab 페이지로 추가합니다.",
        "exist 설정 시 Tabs 의 ID 가 동일한 기존 Tab 페이지의 Context 에 src 속성으로 새로운 WebSquare XML 페이지를 로딩합니다.",
        "select 설정 시 Tabs 의 ID 가 동일한 기존 Tab 페이지를 선택 처리합니다.",
        "last 설정 시 Tabs 의 ID 가 동일한 기존 Tab 페이지의 Tab 버튼 위치를 제일 마지막으로 이동한 후 선택 처리합니다.",
        "Tabs 의 ID 를 기준으로 Tab 페이지의 중복 여부를 판단합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {        
        useConfirmMessage : true, 
        confirmFalseAction : con_confirmFalseAction.getText(),       
    };

    let cList = $c.gcm.createCList(properties);   
    let eList = '';

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:content src="/sample/common_link/tabControl_link_1.xml" style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



scwin.getAfterAction = function () {    
    let confirmFalseAction = con_confirmFalseAction.getText();

    if (confirmFalseAction == "" || "new") {
        target1.setSelectedTabIndex(2);
    }

    let selectedIndex = target1.getSelectedTabIndex();  
    let text = target1.render.textContent;

    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedTabIndex : " + selectedIndex);          
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + text);          
}




scwin.getTabCount = function () {
    let rtn = target1.getTabCount();

    wf_body_bottom.getObj("scwin").setReturnValue("getTabCount : " + rtn);
}



scwin.btn_addTab_onclick = async function (e) {
    let id = "tabs1";

    let rowJSON = {};  

    await target1.addTab(id,  
        {   
            "label": "newTabs", 
            "title": "dataObject",                        
        }, 
        {   
            "src": "/sample/common_link/tabControl_link_2.xml",
            "frameMode" : "wframePreload",
            "scope" : true, 
            "alwaysDraw": "true",
            "dataObject":{
                "type" : "json",
                "name" : "tabParam",
                "data" : rowJSON
            }
        }
    );

    scwin.getTabCount();
    scwin.getAfterAction();
};
